<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryBatch,InventoryItem,InventoryStock,PurchaseOrder,StockMovement,SupplierInvoice};
class ReportController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.reports.index',['lowStock'=>InventoryItem::where('property_id',$p)->whereColumn('quantity_on_hand','<=','reorder_level')->orderBy('quantity_on_hand')->limit(50)->get(),'expiring'=>InventoryBatch::where('property_id',$p)->whereNotNull('expires_at')->whereBetween('expires_at',[today(),today()->addDays(60)])->orderBy('expires_at')->limit(50)->get(),'movements'=>StockMovement::with('inventoryItem')->where('property_id',$p)->latest()->limit(50)->get(),'payables'=>SupplierInvoice::with('supplier')->where('property_id',$p)->whereIn('status',['unpaid','part_paid'])->orderBy('due_date')->limit(50)->get()]);}}